import hashlib
import os
from collections import defaultdict

def get_file_hash(filepath):
    hasher = hashlib.md5()
    try:
        with open(filepath, 'rb') as f:
            while chunk := f.read(8192):
                hasher.update(chunk)
        return hasher.hexdigest()
    except Exception:
        return None

def find_duplicates(root_dir):
    hashes = defaultdict(list)
    for root, _, files in os.walk(root_dir):
        for filename in files:
            filepath = os.path.join(root, filename)
            file_hash = get_file_hash(filepath)
            if file_hash is not None:
                # Get relative path with forward slash as requested
                rel_path = os.path.relpath(filepath, root_dir).replace('\\', '/')
                hashes[file_hash].append(rel_path)

    duplicates = []
    for group in hashes.values():
        if len(group) > 1:
            duplicates.append(sorted(group))

    # Sort groups by their first file's path
    duplicates.sort(key=lambda x: x[0])
    return duplicates

root_dir = 'dosyalar'
duplicate_groups = find_duplicates(root_dir)

with open('kopyalar.txt', 'w', encoding='utf-8') as f:
    for group in duplicate_groups:
        f.write(' | '.join(group) + '\n')

print(f"Found {len(duplicate_groups)} groups of duplicates.")

import hashlib
import os

def get_file_hash(filepath):
    hasher = hashlib.md5()
    try:
        with open(filepath, 'rb') as f:
            while chunk := f.read(8192):
                hasher.update(chunk)
        return hasher.hexdigest()
    except Exception:
        return None

def verify_duplicates(root_dir, expected_groups_file):
    # 1. Find duplicates again manually to verify
    hashes = {}
    for root, _, files in os.walk(root_dir):
        for filename in files:
            filepath = os.path.join(root, filename)
            file_hash = get_file_hash(filepath)
            if file_hash:
                rel_path = os.path.relpath(filepath, root_dir).replace('\\', '/')
                if file_hash not in hashes:
                    hashes[file_hash] = []
                hashes[file_hash].append(rel_path)

    actual_groups = []
    for group in hashes.values():
        if len(group) > 1:
            actual_groups.append(sorted(group))
    actual_groups.sort(key=lambda x: x[0])

    # 2. Read the generated file
    with open(expected_groups_file, 'r', encoding='utf-8') as f:
        lines = [line.strip() for line in f.readlines() if line.strip()]

    # 3. Format actual groups for comparison
    expected_lines = [' | '.join(group) for group in actual_groups]

    print(f"Actual groups found: {len(actual_groups)}")
    print(f"Lines in file: {len(lines)}")

    if set(lines) == set(expected_lines):
        return True, actual_groups
    else:
        return False, actual_groups, lines

root_dir = 'dosyalar'
file_name = 'kopyalar.txt'
is_match, actual, lines = verify_duplicates(root_dir, file_name)

print("--- ACTUAL CONTENT ---")
for l in lines:
    print(l)

if is_match:
    print("\nVERIFICATION SUCCESSFUL: The file matches the calculated duplicates.")
else:
    print("\nVERIFICATION FAILED: The file content does not match.")

